solution.solution.c:
#include <stdlib.h>
#include <string.h>

char *copy_text(const char *s)
{
    size_t size = strlen(s) + 1;
    char *copy = malloc(size);
    if (copy == NULL) return NULL;
    memcpy(copy, s, size);
    return copy;
}

int *make_range(int start, int count)
{
    if (count <= 0) return NULL;
    int *values = malloc((size_t)count * sizeof *values);
    if (values == NULL) return NULL;
    for (int i = 0; i < count; i++) {
        values[i] = start + i;
    }
    return values;
}

char *repeat(const char *s, int times)
{
    if (times < 0) times = 0;
    size_t length = strlen(s);
    char *out = malloc(length * (size_t)times + 1);
    if (out == NULL) return NULL;
    for (int i = 0; i < times; i++) {
        memcpy(out + length * (size_t)i, s, length);
    }
    out[length * (size_t)times] = '\0';
    return out;
}

char *join_with(const char *a, const char *b, char separator)
{
    size_t la = strlen(a);
    size_t lb = strlen(b);
    char *out = malloc(la + 1 + lb + 1);
    if (out == NULL) return NULL;
    memcpy(out, a, la);
    out[la] = separator;
    memcpy(out + la + 1, b, lb + 1);
    return out;
}

unitTests:
TEST("copying text") { const char *original = "hello"; char *c = copy_text(original); CHECK(c != NULL); CHECK_STR(c, "hello"); CHECK(c != original); c[0] = 'j'; CHECK_STR(original, "hello"); free(c); char *e = copy_text(""); CHECK_STR(e, ""); free(e); }
TEST("a range of numbers") { int *r = make_range(5, 4); CHECK(r != NULL); CHECK_EQ(r[0], 5); CHECK_EQ(r[1], 6); CHECK_EQ(r[3], 8); free(r); int *big = make_range(0, 100000); CHECK_EQ(big[99999], 99999); free(big); CHECK(make_range(1, 0) == NULL); }
TEST("repeating") { char *r = repeat("ab", 3); CHECK_STR(r, "ababab"); free(r); r = repeat("x", 1); CHECK_STR(r, "x"); free(r); r = repeat("abc", 0); CHECK_STR(r, ""); free(r); r = repeat("", 5); CHECK_STR(r, ""); free(r); }
TEST("joining") { char *j = join_with("ab", "cd", '-'); CHECK_STR(j, "ab-cd"); free(j); j = join_with("", "", ','); CHECK_STR(j, ","); free(j); j = join_with("home", "user", '/'); CHECK_STR(j, "home/user"); free(j); }

